export const fields=['id','name','type','sector','currency','exposure','as_of','maturity','revenue','ebitda','debt','cash','cfads','debt_service','interest','current_assets','current_liabilities','collateral','pd','lgd','dpd','monthly_income','monthly_payment','coupon','yield','remaining_years'];
const numeric=fields.filter(x=>!['id','name','type','sector','currency','as_of','maturity'].includes(x));
export function ratio(a,b){return Number.isFinite(a)&&Number.isFinite(b)&&b>0?a/b:null;}
export function metrics(r){return {dscr:ratio(r.cfads,r.debt_service),leverage:ratio(r.debt,r.ebitda),netLeverage:ratio(Number.isFinite(r.debt)&&Number.isFinite(r.cash)?r.debt-r.cash:null,r.ebitda),current:ratio(r.current_assets,r.current_liabilities),margin:ratio(r.ebitda,r.revenue),coverage:ratio(r.ebitda,r.interest),dti:ratio(r.monthly_payment,r.monthly_income),el:Number.isFinite(r.pd)&&Number.isFinite(r.lgd)?r.exposure*r.pd*r.lgd:null,ltv:ratio(r.exposure,r.collateral)};}
export function risk(r,policy={dscr:1.2,leverage:4,dti:.4}){const m=metrics(r);const reasons=[];if(r.dpd>=30)reasons.push(`${r.dpd} days past due`);if(r.type==='consumer'){if(m.dti!==null&&m.dti>policy.dti)reasons.push('DTI exceeds policy');}else{if(m.dscr!==null&&m.dscr<policy.dscr)reasons.push('DSCR below policy');if(m.leverage!==null&&m.leverage>policy.leverage)reasons.push('Leverage exceeds policy');}const unavailable=r.type==='consumer'?m.dti===null:m.dscr===null||m.leverage===null;if(!reasons.length&&unavailable)return {level:'Review',reasons:['Key screening metrics unavailable']};return {level:reasons.length?'Watch':r.status==='Review'?'Review':'Pass',reasons};}
export function aggregate(rows,policy){const exposure=rows.reduce((a,r)=>a+r.exposure,0),els=rows.map(r=>metrics(r).el),covered=rows.filter(r=>metrics(r).el!==null).reduce((a,r)=>a+r.exposure,0);const weighted=(key)=>{const usable=rows.filter(r=>metrics(r)[key]!==null);const e=usable.reduce((a,r)=>a+r.exposure,0);return e?usable.reduce((a,r)=>a+metrics(r)[key]*r.exposure,0)/e:null;};return {exposure,el:els.some(x=>x!==null)?els.reduce((a,x)=>a+(x??0),0):null,elCoverage:exposure?covered/exposure:null,dscr:weighted('dscr'),dti:weighted('dti'),leverage:weighted('leverage'),watch:rows.filter(r=>risk(r,policy).level!=='Pass').length,pastDue:rows.filter(r=>r.dpd>=30).reduce((a,r)=>a+r.exposure,0),count:rows.length};}
export function stress(r,{revenue=-15,margin=-3,rate=200,income=-10,pdMultiplier=1.5}={}){const m=metrics(r);const bumpedPd=Number.isFinite(r.pd)?Math.min(1,r.pd*pdMultiplier):null;const el=Number.isFinite(bumpedPd)&&Number.isFinite(r.lgd)?r.exposure*bumpedPd*r.lgd:null;if(r.type==='consumer'){return {dti:ratio(r.monthly_payment,Number.isFinite(r.monthly_income)?r.monthly_income*(1+income/100):null),el,pd:bumpedPd};}const stressedRevenue=Number.isFinite(r.revenue)?r.revenue*(1+revenue/100):null,ebitda=m.margin!==null?stressedRevenue*(m.margin+margin/100):null;const cfads=Number.isFinite(r.cfads)&&r.ebitda>0?r.cfads*ebitda/r.ebitda:null;const incrementalInterest=Number.isFinite(r.debt)?r.debt*rate/10000:null;const debtService=Number.isFinite(r.debt_service)&&incrementalInterest!==null?r.debt_service+incrementalInterest:null;return {revenue:stressedRevenue,ebitda,cfads,debtService,dscr:ratio(cfads,debtService),leverage:ratio(r.debt,ebitda),coverage:ratio(ebitda,Number.isFinite(r.interest)&&incrementalInterest!==null?r.interest+incrementalInterest:null),el,pd:bumpedPd,bondPrice:r.type==='issuer'?bondPrice(r.coupon,Number.isFinite(r.yield)?r.yield+rate/10000:null,r.remaining_years):null};}
export function bondPrice(coupon,yieldRate,years){if(![coupon,yieldRate,years].every(Number.isFinite)||yieldRate<0||years<=0||years>50)return null;const whole=Math.floor(years),fraction=years-whole;let p=0;for(let i=1;i<=whole;i++)p+=100*coupon/(1+yieldRate)**i;if(fraction>0)p+=100*coupon*fraction/(1+yieldRate)**years;return p+100/(1+yieldRate)**years;}
export function parseCSV(text){text=text.replace(/^\uFEFF/,'');const rows=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++;}else if(!quoted&&field!==''){throw Error('Unexpected quote in CSV field');}else quoted=!quoted;}else if(c===','&&!quoted){row.push(field);field='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(x=>x.trim()))rows.push(row);row=[];field='';}else field+=c;}if(quoted)throw Error('Unclosed quoted CSV field');row.push(field);if(row.some(x=>x.trim()))rows.push(row);if(rows.length<2)throw Error('CSV needs a header and at least one data row');const headers=rows.shift().map(x=>x.trim().toLowerCase());if(new Set(headers).size!==headers.length)throw Error('Duplicate CSV headers');return rows.map((r,i)=>{if(r.length!==headers.length)throw Error(`Row ${i+2}: expected ${headers.length} columns, received ${r.length}`);return Object.fromEntries(headers.map((h,j)=>[h,r[j]]));});}
export function validateRows(input){if(!Array.isArray(input)||!input.length||input.length>10000)throw Error('Provide 1 to 10,000 records');const errors=[],ids=new Set();const rows=input.map((raw,i)=>{const r={};for(const f of fields){let v=raw[f];if(numeric.includes(f)){if(v===null||v===undefined||v==='')r[f]=null;else if(typeof v==='boolean'||!Number.isFinite(Number(v))){errors.push(`Row ${i+1}: ${f} must be a number`);r[f]=null;}else r[f]=Number(v);}else r[f]=v===undefined||v===null?'':String(v).trim();}for(const f of ['id','name','type','sector','currency','as_of'])if(!r[f])errors.push(`Row ${i+1}: ${f} is required`);if(!['corporate','consumer','issuer'].includes(r.type))errors.push(`Row ${i+1}: type must be corporate, consumer, or issuer`);if(!/^[A-Z]{3}$/.test(r.currency))errors.push(`Row ${i+1}: currency must be a three-letter uppercase code`);if(r.exposure===null||r.exposure<0)errors.push(`Row ${i+1}: exposure must be zero or positive`);for(const f of ['pd','lgd','coupon','yield'])if(r[f]!==null&&(r[f]<0||r[f]>1))errors.push(`Row ${i+1}: ${f} uses decimals from 0 to 1`);for(const f of numeric.filter(f=>!['ebitda','cfads','pd','lgd','coupon','yield'].includes(f)))if(r[f]!==null&&r[f]<0)errors.push(`Row ${i+1}: ${f} cannot be negative`);if(r.dpd!==null&&!Number.isInteger(r.dpd))errors.push(`Row ${i+1}: dpd must be an integer`);for(const f of ['as_of','maturity'])if(r[f]&&(!/^\d{4}-\d{2}-\d{2}$/.test(r[f])||!Number.isFinite(Date.parse(r[f]))||new Date(r[f]).toISOString().slice(0,10)!==r[f]))errors.push(`Row ${i+1}: ${f} must be a valid YYYY-MM-DD date`);if(ids.has(r.id))errors.push(`Row ${i+1}: duplicate id ${r.id}`);ids.add(r.id);r.status='Pass';r.source='User import';return r;});if(errors.length)throw Error(errors.slice(0,18).join('\n')+(errors.length>18?`\n… and ${errors.length-18} more errors`:''));return rows;}
export function toCSV(rows){const escape=v=>{let s=v===null||v===undefined?'':String(v);if(/^[=+@\t\r]/.test(s)||(/^\-/.test(s)&&!Number.isFinite(Number(s))))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};return fields.map(escape).join(',')+'\n'+rows.map(r=>fields.map(f=>escape(r[f])).join(',')).join('\n');}
